        g.commands.push({ name: "view", icon: "k-i-share", text: "[resource_shortdisplayname[View]]", href: function (data) { return "/Transactions/Credit?Id=" + kendo.htmlEncode(data.Id) + ""; } });
	}
	if(g.expandView) {
