				multi: true,
				search: true,
				dataSource: app.Config.B2B.Currencies.map(c => ({ id: c, name: c }))
			},
			values: app.Config.B2B.Currencies.map(c => ({ id: c, name: c }))
		},
		{ field: "DebtorPaymentDate", title: "[resource_displayname[BuyerPaymentDate]]", width: 80, format: "{0:" + type.dateFormat + "}", type: "date", groupHeaderTemplate: function (data) { return "[resource_shortdisplayname[BuyerPaymentDate]]: " + (kendo.toString(data.value, 'yyyy-MM-dd')) + ""; } },
